376 void MeshModuleStress::calc_total_force()
377 {
378     double surfNorm[3], invSurfArea, temp[3];
379     int nTri = mesh->size();
380 
381     // add wear from this step to total wear
382     if(trackWear())
383     {
384         for(int i = 0; i < nTri; i++)
385         {
386             wear(i) += wear_step(i);
387             wear_step(i) = 0.;
388         }
389     }
390 
391     // calculate normal and shear stress
392     if(trackStress())
393     {
394         // total force and torque on mesh
395 
396         MPI_Sum_Vector(f_total_,3,world);
397         MPI_Sum_Vector(torque_total_,3,world);
398         
399         updatedStresses_ = true; // f_total_ and torque_total_ are now up-to-date
400 
401         for(int i = 0; i < nTri; i++)
402         {
403             // get element surface norm and area
404             mesh->surfaceNorm(i,surfNorm);
405             invSurfArea = 1./mesh->areaElem(i);
406 
407             // calculate normal force
408             sigma_n(i) = vectorDot3D(f(i),surfNorm);
409             
410             // calculate tangential force
411             vectorScalarMult3D(surfNorm,sigma_n(i),temp);
412             vectorSubtract3D(f(i),temp,temp);
413             sigma_t(i) = vectorMag3D(temp);
414 
415             // make both positive
416             // necessary since orientation of surfNorm not known
417             sigma_n(i) = MathExtraLiggghts::abs(sigma_n(i));
418             sigma_t(i) = MathExtraLiggghts::abs(sigma_t(i));
419 
420             // divide by area so have stress
421             sigma_n(i) *= invSurfArea;
422             sigma_t(i) *= invSurfArea;
423             
424         }
425     }
